    catAll: "all",
    catPhone: "phone",
    catTablet: "tablet",
    catDesktop: "desktop",
    catTv: "tv",
    catWatch: "watch"
};
Object.keys(catButtons).forEach(function (id) {
    document.getElementById(id).onclick = function () {
        currentFilter = catButtons[id];
        document.querySelectorAll("#catFilter .btn").forEach(function (b) {
            b.classList.remove("active");
        });
        this.classList.add("active");
        renderTable();
    };
});
document.getElementById("searchInput").addEventListener("input", function () {
    searchQuery = this.value.trim();
    renderTable();
});
/* 表头排序 */
document.querySelectorAll(".devices-table th").forEach(function (th) {
    th.addEventListener("click", function () {
        var col = this.dataset.col;
        if (!col)
            return;
        if (currentSort.col === col) {
            currentSort.dir = currentSort.dir === "asc" ? "desc" : "asc";
        }
        else {
            currentSort.col = col;
            currentSort.dir = "asc";
        }
        updateSortHeaders();
        renderTable();
    });
});
/* 复制表格 */
document.getElementById("btnCopyTable").onclick = function () {
    return __awaiter(this, void 0, void 0, function* () {
        var data = getFilteredDevices();
        if (!data.length) {
            showStatus("无数据", "error");
            return;
        }
        var header = "设备\t类型\t物理宽\t物理高\tCSS宽\tCSS高\tDPR\tPPI\t年份\n";
        var rows = data
            .map(function (d) {
            return [
                d.name,
                CAT_LABEL[d.cat] || d.cat,
                d.physW,
                d.physH,
                d.cssW,
                d.cssH,
                d.dpr + "x",
                d.ppi,
                d.year
            ].join("\t");
        })
            .join("\n");
        try {
            yield navigator.clipboard.writeText(header + rows);
            showStatus("已复制 " + data.length + " 行到剪贴板", "success");
        }
        catch (e) {
            showStatus("复制失败，请手动选择", "error");
        }
    });
};
/* 导出 CSV */
document.getElementById("btnCopyCSV").onclick = function () {
    var data = getFilteredDevices();
    if (!data.length) {
        showStatus("无数据", "error");
        return;
    }
    var header = "Device,Category,Physical Width,Physical Height,CSS Width,CSS Height,DPR,PPI,Year\n";
    var rows = data
        .map(function (d) {
        var escapedName = '"' + d.name.replace(/"/g, '""') + '"';
        return [
            escapedName,
            CAT_LABEL[d.cat] || d.cat,
            d.physW,
            d.physH,
            d.cssW,
            d.cssH,
            d.dpr,
            d.ppi,
            d.year
        ].join(",");
    })
        .join("\n");
    var csv = header + rows;
    var blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "screen-resolution-reference.csv";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showStatus("CSV 已下载（" + data.length + " 行）", "success");
};
function showStatus(msg, type) {
    var el = document.getElementById("statusEl");
    el.textContent = msg;
    el.className = "status " + (type || "");
}
/* ── 初始化 ── */
detectCurrentDevice();
updateSortHeaders();
renderTable();
window.toggleTheme = function () {
    var html = document.documentElement;
    var currentTheme = html.getAttribute("data-theme") || "dark";
    var newTheme = currentTheme === "light" ? "dark" : "light";
    html.setAttribute("data-theme", newTheme);
    localStorage.setItem("theme", newTheme);
};
function initTheme() {
    var savedTheme = localStorage.getItem("theme");
    var prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    var theme = savedTheme || (prefersDark ? "dark" : "light");
    document.documentElement.setAttribute("data-theme", theme);
}
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", function (e) {
    if (!localStorage.getItem("theme"))
        document.documentElement.setAttribute("data-theme", e.matches ? "dark" : "light");
});
initTheme();
